import {TRAILS,UPGRADES,scoreForDiameter,buyTrail,buyUpgrade} from './progression.mjs';
import {COURSES,LOOKS,ITEMS,CHAPTERS,CHAPTER_ITEMS,ITEM_COUNT,ITEM_STORIES,COURSE_POOLS,WORLD_METRES,clamp} from './data.mjs';
import {createRace,stepRace,result,settle,normalizeSave,buyLook,canCollect} from './rules.mjs';
import {expectedAt} from './course.mjs';
import {screenToTrack,trackToScreen,steeringTarget,dragTarget} from './presentation.mjs';
import {sceneryTypesFor} from './scenery.mjs';
import {START_RADIUS} from './course.mjs';
import {RollScene} from './scene.mjs';
const canvas=document.querySelector('#world'),ui=document.querySelector('#ui'),notices=document.querySelector('#notices'),music=document.querySelector('#music'),qa=new URLSearchParams(location.search).has('qa'),SAVE_KEY='roll-it-all-v1'+(qa?'-qa':'');
function load(){try{return normalizeSave(JSON.parse(localStorage.getItem(SAVE_KEY)));}catch{return normalizeSave(null);}}
let save=load(),world=createRace(save.course,71,save),scene,view='home',last=performance.now(),hudClock=0,countdown=2.3,countBeat=3,keys=new Set(),drag=null,heldSteer=0,steerId=null,steerDownAt=0,lastSteerDuration=0,lineTarget=null,jumpQueue=false,powerQueue=false,previewLook=save.look,previewTrail=save.trail,shopTab='looks',albumChapter=0,audio=null,collectSoundAt=-2,lastName='',lastItem=-10;
try{scene=new RollScene(canvas);scene.applyLook(save.look);scene.applyTrail(save.trail);scene.build(world);}catch(e){document.querySelector('#loading').innerHTML='<b>小世界还没打开</b><span>请使用支持WebGL的浏览器后刷新</span>';console.error(e);throw e;}
const sizeText=worldSize=>{const cm=Math.max(0,Math.floor(worldSize*WORLD_METRES*100+1e-7));return cm<100?cm+'cm':(Math.floor(cm/10)/10).toFixed(1)+'m';};
const timeText=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(1).padStart(4,'0')}`;
const coin=()=>`<div class="wallet" aria-label="成长积分余额"><span>✦</span><b>${save.coins}</b></div>`;

const pendingAudioNotes=new Set();let audioGeneration=0;
function delaySound(callback,delay){const generation=audioGeneration;let id;id=setTimeout(()=>{pendingAudioNotes.delete(id);if(generation===audioGeneration)callback();},delay);pendingAudioNotes.add(id);}
function cancelAudioNotes(){audioGeneration++;for(const id of pendingAudioNotes)clearTimeout(id);pendingAudioNotes.clear();}
function stopMusic(reset=false){music.pause();if(reset)music.currentTime=0;}
function startMusic(reset=false){if(!save.sound||view!=='race'||world.mode==='paused'||document.hidden)return;if(reset)music.currentTime=0;music.volume=.16;music.play().catch(()=>{});}
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch{toast('浏览器暂时无法保存进度');}}
function resetInput(){keys.clear();drag=null;heldSteer=0;steerId=null;lineTarget=null;jumpQueue=powerQueue=false;ui.querySelectorAll('[data-steer]').forEach(b=>b.classList.remove('pressed'));}
function unlockAudio(){if(!save.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();}catch{}}
function note(freq,duration=.14,gain=.05,type='sine',end){if(world.mode==='paused'||!save.sound||!audio||audio.state!=='running')return;const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,now);if(end)o.frequency.exponentialRampToValueAtTime(end,now+duration);g.gain.setValueAtTime(.001,now);g.gain.exponentialRampToValueAtTime(gain,now+.008);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g).connect(audio.destination);o.start();o.stop(now+duration+.02);}
function sfx(type){if(type==='collect'){if(world.time-collectSoundAt<.07)return;collectSoundAt=world.time;note(420+world.players[0].combo%8*67,.105,.027,'sine');}else if(type==='jump')note(220,.2,.04,'triangle',650);else if(type==='land')note(280,.13,.04,'sine',140);else if(type==='bump')note(140,.19,.045,'triangle',62);else if(type==='power')note(180,.35,.05,'triangle',900);else if(type==='ready'){[523,659,784].forEach((f,i)=>delaySound(()=>note(f,.16,.035),i*70));}else if(type==='finish'){[523,659,784,1046].forEach((f,i)=>delaySound(()=>note(f,.25,.04,'triangle'),i*100));}}
function toast(text,kind=''){const el=document.createElement('div');el.className='toast '+kind;el.textContent=text;notices.replaceChildren(el);setTimeout(()=>el.remove(),2000);}
function header(back=false){return `<header class="top">${back?'<button class="icon back" data-action="home" aria-label="回到主页">‹</button>':'<div class="logo"><i>✳</i><span>ROLL IT ALL<small>小小东西，大大世界</small></span></div>'}${coin()}${back?'':`<button class="icon" data-action="sound" aria-label="${save.sound?'关闭声音':'开启声音'}">${save.sound?'♪':'♩'}</button><button class="icon" data-action="help" aria-label="玩法说明">?</button>`}</header>`;}
function home(){stopMusic(true);cancelAudioNotes();resetInput();view='home';save=load();world=createRace(save.course,71,save);previewLook=save.look;scene.build(world);scene.applyLook(save.look);scene.applyTrail(save.trail);notices.replaceChildren();renderHome();}
function renderHome(){const c=COURSES.find(c=>c.id===save.course);ui.innerHTML=`<section class="screen home">${header()}<div class="hero"><small class="eyebrow">SMALL THINGS. BIG ADVENTURES.</small><h1>万物<em>滚滚</em><i>✳</i></h1><p>把整个世界，滚成一团。</p><button class="collection-chip" data-action="album"><span>▧</span> 我的收藏 <b>${save.discovered.length}<small>/ ${ITEM_COUNT}</small></b></button></div><div class="home-bottom"><div class="route-line"><span>本次旅程</span><b>${c.name}</b><button data-action="courses">换一条路线 ↗</button></div><button class="primary" data-action="start">开始滚动 <span>→</span></button><div class="secondary-row"><button class="secondary" data-action="shop"><span>✿</span> 成长工坊</button><button class="secondary" data-action="album"><span>▧</span> 万物图鉴</button></div><p class="foot">单人成长 · 最大直径每10厘米可得2积分</p></div></section>`;}
function chooseCourses(){const thumbs=scene.courseThumbnails();ui.insertAdjacentHTML('beforeend',`<div class="modal" id="course-select"><section class="panel courses"><small class="eyebrow">A LITTLE CHANGE OF SCENERY</small><h2>今天，从哪里出发？</h2><div class="course-list">${COURSES.map((c,i)=>`<button class="course-card ${c.id===save.course?'selected':''}" data-course="${c.id}" aria-label="选择${c.name}"><img class="course-mini" src="${thumbs.get(c.id)}" alt="${c.name}三维路线缩景"><span><b>${c.name}</b><small>${c.tag}</small><small>✦ 特别纪念物：${ITEMS[c.souvenir].name}</small><em>${save.bestSizes[c.id]?'最大 '+sizeText(save.bestSizes[c.id])+' · 最快 '+timeText(save.bestTimes[c.id]):'一段还没卷起来的新旅程'}</em></span><strong>${c.id===save.course?'✓':'↗'}</strong></button>`).join('')}</div><button class="text-button" data-action="close">回到小世界</button></section></div>`);}
function start(){stopMusic(true);cancelAudioNotes();unlockAudio();resetInput();save=load();world=createRace(save.course,qa&&Number.isFinite(Number(new URLSearchParams(location.search).get('seed')))&&new URLSearchParams(location.search).has('seed')?Number(new URLSearchParams(location.search).get('seed')):Date.now()%100000,save);world.mode='countdown';view='race';countdown=2.5;countBeat=3;note(392,.08,.026,'sine');hudClock=0;collectSoundAt=-2;lastName='';lastItem=-10;notices.replaceChildren();scene.build(world);scene.applyLook(save.look);scene.applyTrail(save.trail);ui.innerHTML=`<section class="screen race"><header class="race-top"><div class="place solo-points"><b id="run-score">2</b><small>本局<br>成长积分</small></div><div class="race-chapter"><small id="chapter-kicker">第一站</small><b id="chapter">桌面奇遇</b><span id="timer">00:00.0</span></div><button class="icon" data-action="pause" aria-label="暂停挑战">Ⅱ</button></header><div class="journey"><i id="progress"></i><b style="left:${world.track.chapterStarts[1]/world.track.length*100}%"></b><b style="left:${world.track.chapterStarts[2]/world.track.length*100}%"></b><b></b></div><div class="size-readout"><small>现在这么大</small><b id="size">10<em>cm</em></b><span id="growth-hint">小东西，也有大冒险</span><small id="growth-status"></small><small id="equipped-powers"></small></div><div class="collect-readout" id="collect-readout"><span id="last-item">✦</span><b id="collect-name">看见小东西？滚过去！</b><small id="collect-count">已卷起 0 件</small></div><div id="chapter-toast" class="chapter-toast" hidden></div><div class="interaction-legend" aria-label="物件提示：绿色加号可吸收，红色感叹号注意碰撞"><span class="cue-collect"><b>＋</b>可吸收</span><span class="cue-danger"><b>!</b><i id="danger-legend">碰撞会掉落</i></span></div><div class="tip" id="tip">左右拖动选路，把小东西卷起来</div><div class="lane-indicator"><div class="lane-track"><i id="lane-marker"></i></div><span id="lane-status">居中</span></div><div class="steer-buttons"><button data-steer="-1" aria-label="向左滚动">‹</button><button data-steer="1" aria-label="向右滚动">›</button></div><button class="power-button" data-action="power" aria-label="聚合冲刺" disabled><span>✳</span><b id="power-label">聚合冲刺</b><small id="power-sub">收集来蓄能</small><i id="power-fill"></i></button><button class="jump-button" data-action="jump" aria-label="起跳"><span>↟</span><b>跃一下</b><small>SPACE / 点击</small></button><div class="countdown" id="countdown">准备出发</div></section>`;hud();startMusic(true);}
function hud(){const p=world.players[0],size=sizeText(p.radius*2),unit=size.endsWith('cm')?'cm':'m';document.querySelector('#run-score').textContent=scoreForDiameter(Math.max(p.radius,p.peakRadius||START_RADIUS)*2);document.querySelector('#danger-legend').textContent=p.power>0?'太大 · 冲刺保护':p.shieldCharges>0?'太大 · 护盾可挡':p.grace>0?'太大 · 暂时保护':'碰撞会掉落';document.querySelector('#equipped-powers').textContent='冲刺 '+(4+p.upgrades.duration)+'s'+(p.upgrades.magnet?' · 磁力 Lv.'+p.upgrades.magnet:'')+(p.upgrades.shield?' · 护盾 '+p.shieldCharges:'');document.querySelector('#timer').textContent=timeText(world.time);document.querySelector('#progress').style.width=p.s/world.track.length*100+'%';document.querySelector('#size').innerHTML=size.replace(unit,'')+'<em>'+unit+'</em>';document.querySelector('#chapter').textContent=CHAPTERS[p.chapter].name;document.querySelector('#chapter-kicker').textContent=['第一站 · 小小出发','第二站 · 世界变小了','第三站 · 把小镇卷起来'][p.chapter];document.querySelector('#size').classList.toggle('growing',world.time-lastItem<.4);document.querySelector('#growth-status').textContent=p.collected?'本局最大 '+sizeText(Math.max(p.radius,p.peakRadius)*2):'从10cm开始，卷起小物件长大';document.querySelector('#growth-hint').textContent=p.radius<1?'先从糖果和小玩具开始':p.radius<4?'世界正在变小，试试更多东西':p.radius<10?'走上街道，带走路边的小物件':'车辆、小屋，也能一起卷走';document.querySelector('#lane-marker').style.left=(trackToScreen(p.u)/.94+1)*50+'%';document.querySelector('#lane-status').textContent=p.u>.6?'靠左':p.u>.2?'偏左':p.u<-.6?'靠右':p.u<-.2?'偏右':'居中';document.querySelector('#collect-count').textContent='已卷起 '+p.collected+' 件';const streak=p.combo>=3&&world.time-p.lastCollect<2.3;document.querySelector('#last-item').textContent=streak?'×'+p.combo:'✦';document.querySelector('#last-item').classList.toggle('combo',streak);document.querySelector('#collect-name').textContent=lastName||'看见小东西？滚过去！';document.querySelector('#collect-readout').classList.toggle('recent',world.time-lastItem<.6);const power=document.querySelector('.power-button');power.disabled=world.mode!=='play'||p.energy<100||p.power>0;power.classList.toggle('ready',p.energy>=100);power.classList.toggle('active',p.power>0);document.querySelector('#power-fill').style.height=p.energy+'%';document.querySelector('#power-label').textContent=p.power>0?'卷起来！':p.energy>=100?'冲一波':'聚合冲刺';document.querySelector('#power-sub').textContent=p.power>0?p.power.toFixed(1)+'s':p.energy>=100?'点击 / F':Math.floor(p.energy)+'%';document.querySelector('.jump-button').disabled=world.mode!=='play'||p.airDuration>0||p.jumpCooldown>0;document.querySelector('#countdown').textContent=world.mode==='countdown'?countdown>1?Math.ceil(countdown):'滚起来！':'';const expected=expectedAt(world.track,p.s),souvenir=world.track.items.find(i=>i.rare&&!(i.takenBy&1)&&i.s>p.s&&i.s-p.s<p.speed*6+p.radius*6),near=world.track.obstacles.find(o=>o.s>p.s&&o.s-p.s<p.speed*2.2+p.radius*3&&Math.abs((o.kind==='sweeper'?o.u+Math.sin(world.time*1.3+o.phase)*.17:o.u)-p.u)*expected.width<p.radius+o.r*1.2),big=world.track.items.find(i=>!(i.takenBy&1)&&i.s>p.s&&i.s-p.s<p.speed*2.1+p.radius*3&&!canCollect(p,i)&&Math.abs(i.u-p.u)*expected.width<p.radius+i.r*.82),hazard=p.power>0?null:near&&big?(near.s<big.s?near:big):near||big,jumpWindow=hazard&&hazard.s-p.s<p.radius+hazard.r*.65+p.speed*.32,canJump=world.mode==='play'&&p.airDuration===0&&p.jumpCooldown===0;document.querySelector('.jump-button').classList.toggle('ready',!!jumpWindow&&canJump);document.querySelector('.jump-button>b').textContent=jumpWindow&&canJump?'现在起跳':'跃一下';document.querySelector('#tip').textContent=p.airDuration>0?'轻轻落地，接着把世界卷起来':jumpWindow?(hazard===big?'这个还太大 · 现在跃一下或换条路':'现在跃一下 · 跨过前方缓冲杆'):souvenir?'✦ 发光收藏在'+(souvenir.u<0?'右侧':'左侧')+(souvenir.hop?' · 靠边上斜坡跃起拿到它':' · 靠近把它卷走'):hazard?(hazard===big?'前方物品还太大 · 绕开它，或靠近后跃一下':'前方缓冲杆 · 接近时跃一下'):p.power>0?'聚合冲刺 · 吸附加速，抵挡磕碰！':world.time<8?'左右拖动选路，绿圈＋可吸收，红圈！先避开':'沿着绿色＋选路，长大后红圈也会变绿';document.querySelector('#tip').classList.toggle('warning',!!hazard&&p.airDuration===0);}
function event(e){scene.event(e,world);if(e.player!==0)return;if(e.type==='collect'){lastName=ITEMS[e.itemType].name;lastItem=world.time;sfx('collect');if(ITEMS[e.itemType].rare){sfx('ready');toast('✦ 收到 '+lastName+'，这一趟的特别纪念物！');}}if(e.type==='jump')sfx('jump');if(e.type==='land')sfx('land');if(e.type==='power'){sfx('power');toast('聚合冲刺 · 把这一片卷走！','power');}if(e.type==='power-ready'){sfx('ready');toast('冲刺蓄满啦 · 点左下角冲一波');}if(e.type==='power-guard')note(620,.08,.022,'sine');if(e.type==='shield-guard'){sfx('ready');toast('护盾挡住了 · 剩余 '+e.remaining+' 次');}if(e.type==='bump'){sfx('bump');toast('磕碰减速'+(e.removed.length?' · 掉落 '+e.removed.length+' 件':'')+' · 最大尺寸积分保留');}if(e.type==='chapter'){sfx('ready');const el=document.querySelector('#chapter-toast');el.innerHTML=`<small>HELLO, BIGGER WORLD</small><b>${CHAPTERS[e.chapter].name}</b><span>${CHAPTERS[e.chapter].subtitle}</span>`;el.hidden=false;setTimeout(()=>el.hidden=true,1500);}if(e.type==='finish')sfx('finish');}
function end(){stopMusic();view='result';resetInput();save=load();const oldSize=save.bestSizes[world.track.id]||0,oldTypes=new Set(save.discovered),r=settle(world,save),newTypes=r.types.filter(t=>!oldTypes.has(t));persist();hud();ui.insertAdjacentHTML('beforeend',`<div class="modal result-modal"><section class="panel result"><small class="eyebrow">SOLO GROWTH CHALLENGE</small><div class="result-rank">${r.peakDiameter>oldSize?'✦ 新的最大纪录':'又卷大了一点'}</div><h2>${r.finished?'这一趟，卷得真大！':'又长大了一点！'}</h2><div class="result-size"><small>本局最大球直径</small><b>${sizeText(r.peakDiameter)}</b><span>结算时 ${sizeText(r.diameter)}${newTypes.length?' · 新发现 '+newTypes.length+' 种':''}</span></div><div class="stats"><div><small>卷起物品</small><b>${r.collected} 件</b></div><div><small>挑战时间</small><b>${timeText(r.time)}</b></div><div><small>磕碰次数</small><b>${r.bumps} 次</b></div><div><small>聚合冲刺</small><b>${r.powerUses} 次</b></div></div><div class="reward"><b>✦ +${r.score}</b><span>成长积分已到账<br>最大直径每满10cm得2分</span></div><button class="primary" data-action="start">再长大一次 <span>→</span></button><div class="secondary-row"><button class="secondary" data-action="shop">去成长工坊</button><button class="secondary" data-action="next">下一条路线</button></div><div class="result-footer"><button class="text-button" data-action="album">看看新收藏 ↗</button><button class="text-button" data-action="home">回到小世界</button></div></section></div>`);}
function pause(){if(view!=='race'||world.mode==='paused')return;world.beforePause=world.mode;world.mode='paused';stopMusic();cancelAudioNotes();audio?.suspend();resetInput();const p=world.players[0],peak=Math.max(p.radius,p.peakRadius);ui.insertAdjacentHTML('beforeend',`<div class="modal" id="pause"><section class="panel pause"><small class="eyebrow">TAKE A LITTLE BREATHER</small><h2>小世界，等你一会儿。</h2><p>本局最大 ${sizeText(peak*2)} · 可结算 ${scoreForDiameter(peak*2)} 积分</p><p class="pause-rule">继续长大刷新成绩。重开或返回主页不结算本局。</p><div class="audio-row"><span>配乐与音效</span><button data-action="toggle-sound" aria-pressed="${save.sound}">声音：${save.sound?'开启':'关闭'}</button></div><button class="primary" data-action="resume">继续滚动 <span>→</span></button><button class="secondary full" data-action="start">重新出发</button><button class="text-button" data-action="home">回到小世界</button></section></div>`);}
function resume(){unlockAudio();document.querySelector('#pause')?.remove();world.mode=world.beforePause||'play';startMusic();last=performance.now();}
function shop(){resetInput();view='shop';save=load();previewLook=save.look;previewTrail=save.trail;shopTab='looks';renderShop();}
function renderShop(){
 const look=LOOKS.find(x=>x.id===previewLook),trail=TRAILS.find(t=>t.id===previewTrail);scene.applyLook(shopTab==='looks'?look.id:save.look);scene.applyTrail(shopTab==='trails'?trail.id:save.trail);const thumbnails=scene.lookThumbnails?.()||new Map();
 const tabs=`<div class="shop-tabs" role="tablist" aria-label="成长工坊分类">${[['looks','服装'],['trails','尾迹'],['powers','能力']].map(([id,label])=>`<button role="tab" aria-selected="${shopTab===id}" data-shop-tab="${id}">${label}</button>`).join('')}</div>`;
 let name,description,content;
 if(shopTab==='looks'){const owned=save.owned.includes(look.id);name=look.name;description=owned?'已经拥有 · 可随时换穿':'随意试穿，喜欢了再带走';content=`<div class="look-grid">${LOOKS.map(x=>`<button class="look ${previewLook===x.id?'selected':''}" data-look="${x.id}" aria-label="试穿${x.name}" aria-pressed="${previewLook===x.id}"><span>${save.owned.includes(x.id)?'已拥有':x.price+' ✦'}</span><img src="${thumbnails.get(x.id)}" alt="${x.name}实际三维外观"><b>${x.name}</b></button>`).join('')}</div><button class="primary" data-action="buy" ${!owned&&save.coins<look.price?'disabled':''}>${owned?(save.look===look.id?'已经穿好啦':'穿这套出发'):save.coins>=look.price?'解锁并穿上 · '+look.price+' 积分':'还差 '+(look.price-save.coins)+' 积分'}</button><p class="shop-note">服装只改变外观 · 拖动小世界可以旋转</p>`;}
 else if(shopTab==='trails'){const owned=save.ownedTrails.includes(trail.id);name=trail.name;description=trail.note;content=`<div class="look-grid trail-grid">${TRAILS.map(t=>`<button class="look trail-card ${trail.id===t.id?'selected':''}" data-trail="${t.id}" aria-label="预览${t.name}" aria-pressed="${trail.id===t.id}"><span>${save.ownedTrails.includes(t.id)?'已拥有':t.price+' ✦'}</span><i style="--color:${t.colors[0]};--accent:${t.colors[1]||'#fff9df'}">${t.icon}</i><b>${t.name}</b></button>`).join('')}</div><button class="primary" data-action="buy-trail" ${!owned&&save.coins<trail.price?'disabled':''}>${owned?(save.trail===trail.id?'已装备这款尾迹':'装备这款尾迹'):save.coins>=trail.price?'解锁并装备 · '+trail.price+' 积分':'还差 '+(trail.price-save.coins)+' 积分'}</button><p class="shop-note">移动尾迹与脚下光圈 · 只改变外观</p>`;}
 else{name='把下一趟，滚得更轻松';description='永久升级 · 下一局生效 · 每局护盾补满';content=`<div class="upgrade-list">${UPGRADES.map(u=>{const level=save.upgrades[u.id],max=level===u.prices.length,cost=u.prices[level];return `<article class="upgrade-card"><div class="upgrade-icon">${u.icon}</div><div><h4>${u.name} <small>Lv.${level}/3</small></h4><p>${u.effect(level)}</p><small>${max?'已达到最高等级':'下一级：'+u.effect(level+1)}</small></div><button data-upgrade="${u.id}" aria-label="升级${u.name}" ${max||save.coins<cost?'disabled':''}>${max?'已满级':cost+' ✦<br>升级'}</button></article>`;}).join('')}</div><p class="shop-note">每项独立升级，当前积分可跨多局积累</p>`;}
 ui.innerHTML=`<section class="screen shop ${shopTab==='powers'?'powers-shop':''}">${header(true)}${tabs}<div class="shop-title"><small class="eyebrow">成长工坊 · ${shopTab==='looks'?'服装':shopTab==='trails'?'尾迹与脚下特效':'能力升级'}</small><h3>${name}</h3><p>${description}</p></div><div class="shop-bottom">${content}<button class="text-button" data-action="start">准备好了，去长大 →</button></div></section>`;
}
function album(){resetInput();view='album';save=load();scene.applyLook(save.look);scene.applyTrail(save.trail);renderAlbum();}
function renderAlbum(){const thumbs=scene.thumbnails?.()||new Map(),types=CHAPTER_ITEMS[albumChapter];ui.innerHTML=`<section class="screen album">${header(true)}<div class="album-head"><small class="eyebrow">EVERY LITTLE THING COUNTS</small><h2>我的万物图鉴</h2><p>已经卷起过 <b>${save.discovered.length}</b> / ${ITEM_COUNT} 种小美好</p><div class="album-tabs">${CHAPTERS.map((c,i)=>`<button data-album="${i}" class="${i===albumChapter?'selected':''}">${c.name}</button>`).join('')}</div></div><div class="album-grid">${types.map(t=>`<button class="collection ${save.discovered.includes(t)?'found':''}" data-item="${t}" aria-label="查看${ITEMS[t].name}"><span>${save.discovered.includes(t)?'✦ 已发现':'还没卷到'}</span>${thumbs.get(t)?`<img src="${thumbs.get(t)}" alt="${ITEMS[t].name}三维模型">`:`<i style="color:${ITEMS[t].color}">✳</i>`}<b>${ITEMS[t].name}</b></button>`).join('')}</div><button class="primary album-roll" data-action="start">出发，再找一点新东西 <span>→</span></button></section>`;}
function itemDetails(type){const item=ITEMS[type];if(!item)return;const found=save.discovered.includes(type),routes=COURSES.filter(c=>c.souvenir===type||COURSE_POOLS[c.id].some(pool=>pool.includes(type))||sceneryTypesFor(c.id).has(type));ui.insertAdjacentHTML('beforeend',`<div class="modal" id="item-details" role="dialog" aria-modal="true" aria-label="${item.name}收藏详情"><section class="panel item-details"><small class="eyebrow">${item.rare?'A VERY SPECIAL LITTLE FIND':'A PIECE OF YOUR LITTLE WORLD'}</small><div class="detail-badge">${item.rare?'✦ 路线限定纪念物':'小小世界的一部分'}</div><img class="detail-model ${found?'':'undiscovered'}" src="${scene.thumbnails().get(type)}" alt="${item.name}实际三维模型"><h2>${item.name}</h2><p class="detail-status">${found?'✦ 已经在旅途中发现':'还没卷到，下一趟去找找吧'}</p><p class="detail-story">${ITEM_STORIES[type]}</p><div class="detail-routes"><small>可以在哪里找到</small><div>${routes.map(c=>`<span>${c.name}</span>`).join('')}</div></div><button class="primary" data-action="close">收好这份小美好 <span>✓</span></button></section></div>`);}
function help(){ui.insertAdjacentHTML('beforeend',`<div class="modal" id="help"><section class="panel help"><small class="eyebrow">SOLO GROWTH CHALLENGE</small><h2>看看你能卷多大。</h2><div class="help-lines"><p><b>单人成长，挑战自己的最大尺寸。</b>自动前进；拖动、左右按钮或A/D选路，空格或右下角起跳。绿色＋可吸收，红色！碰撞有惩罚，先绕开或跃过。</p><p><b>最大直径每10cm得2积分。</b>50cm得10分，1m得20分，5m得100分，10m得200分。按本局达到过的最大直径结算，之后被撞小也不扣成绩。到终点或时间结束自动到账，主动重开或退出不结算。</p><p><b>碰撞有轻惩罚，冲刺与护盾可保护。</b>撞大物件或障碍杆：体积减少3.5%，减速0.9秒，并有1.1秒保护；通常掉1至3件，刚起步的小球不掉物件。收集蓄满后冲刺，基础4秒免受碰撞惩罚。</p><p><b>积分积累，解锁自己的风格与能力。</b>成长工坊可买服装、移动尾迹和脚下光圈，或升级冲刺时间、吸附范围、每局护盾。服装和尾迹只改变外观；能力下一局生效，永久保留。</p></div><button class="primary" data-action="close">明白啦，去长大 <span>→</span></button></section></div>`);}
ui.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;unlockAudio();if(view!=='race'&&b.dataset.action!=='sound')note(360,.06,.014,'sine',440);if(b.dataset.steer!==undefined){if(view==='race'&&world.mode==='play'&&(lastSteerDuration<220||e.detail===0))lineTarget=steeringTarget(lineTarget??world.players[0].u,Number(b.dataset.steer));return;}if(b.dataset.course){save.course=b.dataset.course;persist();home();return;}if(b.dataset.shopTab){shopTab=b.dataset.shopTab;renderShop();return;}if(b.dataset.trail){previewTrail=b.dataset.trail;renderShop();return;}if(b.dataset.upgrade){save=load();if(buyUpgrade(save,b.dataset.upgrade)){persist();renderShop();toast('升级完成 · 下一局生效');}return;}if(b.dataset.look){previewLook=b.dataset.look;renderShop();return;}if(b.dataset.item){itemDetails(b.dataset.item);return;}if(b.dataset.album!==undefined){albumChapter=Number(b.dataset.album);renderAlbum();return;}switch(b.dataset.action){case'start':start();break;case'home':home();break;case'shop':shop();break;case'album':album();break;case'courses':chooseCourses();break;case'help':help();break;case'close':document.querySelector('.modal:last-child')?.remove();break;case'pause':pause();break;case'resume':resume();break;case'jump':jumpQueue=true;break;case'power':powerQueue=true;break;case'sound':save.sound=!save.sound;persist();if(!save.sound){stopMusic();cancelAudioNotes();audio?.suspend();}renderHome();break;case'toggle-sound':save.sound=!save.sound;persist();if(!save.sound){stopMusic();cancelAudioNotes();audio?.suspend();}b.textContent='声音：'+(save.sound?'开启':'关闭');b.setAttribute('aria-pressed',String(save.sound));break;case'next':save.course=COURSES[(COURSES.findIndex(c=>c.id===save.course)+1)%COURSES.length].id;persist();home();break;case'buy-trail':save=load();if(buyTrail(save,previewTrail)){persist();renderShop();toast('尾迹已装备，去留下一点光！');}break;case'buy':save=load();if(buyLook(save,previewLook)){persist();renderShop();toast('穿好啦，世界在等你！');}break;}});
ui.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-steer]');if(!b||view!=='race'||world.mode!=='play')return;e.preventDefault();heldSteer=screenToTrack(Number(b.dataset.steer));steerDownAt=performance.now();steerId=e.pointerId;b.classList.add('pressed');b.setPointerCapture(e.pointerId);});
function release(e){if(steerId===e.pointerId){lastSteerDuration=performance.now()-steerDownAt;heldSteer=0;steerId=null;ui.querySelectorAll('[data-steer]').forEach(b=>b.classList.remove('pressed'));}if(drag?.id===e.pointerId)drag=null;}
ui.addEventListener('pointerup',release);ui.addEventListener('pointercancel',release);canvas.addEventListener('pointerdown',e=>{if(!['home','shop','race'].includes(view)||view==='race'&&world.mode!=='play')return;lineTarget=null;drag={id:e.pointerId,start:e.clientX,last:e.clientX,u:world.players[0].u,preview:view!=='race'};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag?.id!==e.pointerId)return;if(drag.preview)scene.homeYaw+=(e.clientX-drag.last)*.012;drag.last=e.clientX;});canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',release);
addEventListener('keydown',e=>{const modal=document.querySelector('.modal:last-child');if(e.code==='Tab'&&modal){const controls=[...modal.querySelectorAll('button:not(:disabled)')];if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(!modal.contains(document.activeElement)||e.shiftKey&&document.activeElement===first){e.preventDefault();(e.shiftKey?last:first).focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(e.code==='Escape'){if(modal&&!modal.classList.contains('result-modal')&&modal.id!=='pause'){modal.remove();return;}if(world.mode==='paused')resume();else pause();return;}if(view!=='race'||world.mode!=='play')return;if(e.code==='Space'&&e.target.closest?.('button')&&!e.target.closest?.('[data-steer]'))return;if(['ArrowLeft','ArrowRight','Space','KeyF','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='Space')jumpQueue=true;if(!e.repeat&&['KeyF','ShiftLeft','ShiftRight'].includes(e.code))powerQueue=true;});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();audio?.suspend();}else last=performance.now();});addEventListener('resize',()=>scene.resize());
function input(){const value={steer:screenToTrack((keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0))||heldSteer,jump:jumpQueue,power:powerQueue};jumpQueue=powerQueue=false;if(value.steer&&(!heldSteer||performance.now()-steerDownAt>220))lineTarget=null;if(lineTarget!==null){value.targetU=lineTarget;if(Math.abs(world.players[0].u-lineTarget)<.006)lineTarget=null;}if(drag&&!drag.preview)value.targetU=dragTarget(drag.u,drag.last-drag.start,canvas.clientWidth);return value;}
const qaPerf={at:performance.now(),frames:0};
function frame(now){requestAnimationFrame(frame);qaPerf.frames++;if(qa&&now-qaPerf.at>=10000){console.info('ROLL_QA_PERF '+JSON.stringify({fps:Number((qaPerf.frames*1000/(now-qaPerf.at)).toFixed(1)),calls:scene.renderer.info.render.calls,triangles:scene.renderer.info.render.triangles,viewport:[canvas.clientWidth,canvas.clientHeight]}));qaPerf.at=now;qaPerf.frames=0;}const dt=Math.min(.1,Math.max(0,(now-last)/1000));last=now;if(view==='race'&&world.mode!=='paused'){if(world.mode==='countdown'){countdown-=dt;const beat=countdown>1?Math.ceil(countdown):0;if(beat!==countBeat){countBeat=beat;note(beat?392:784,beat?.08:.18,beat?.026:.035,'sine');}if(countdown<=0)world.mode='play';}else{let left=dt;const controls=input();while(left>0&&world.mode==='play'){const step=Math.min(left,1/60);stepRace(world,step,controls);controls.jump=controls.power=false;for(const e of world.events)event(e);left-=step;}if(world.mode==='result')end();}hudClock+=dt;if(hudClock>.07&&view==='race'){hud();hudClock=0;}}scene.render(world,dt,view);}
