.collection{cursor:pointer;width:100%;color:inherit}.collection:active{transform:scale(.98)}.detail-badge{display:table;margin:14px auto 0;padding:5px 11px;background:#ecdfb8;color:#a0874e;border:1px solid #fff8dc;border-radius:20px;font-size:9px}.detail-model{display:block;margin:2px auto -6px;width:min(230px,100%);height:205px;object-fit:contain;filter:drop-shadow(0 10px 7px #66806715)}.detail-model.undiscovered{filter:grayscale(1);opacity:.45}.item-details h2{margin:2px 0 7px;font-size:27px}.detail-status{font-size:10px;color:#b2944b}.detail-story{font-size:12px;line-height:1.9;margin:15px 3px;color:#748774}.detail-routes{background:#eeebd8;border-radius:13px;padding:11px 8px;margin:14px 0 18px}.detail-routes>small{font-size:9px;color:#8c977d}.detail-routes>div{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:8px}.detail-routes span{background:#faf2dc;border:1px solid #fff9e9;border-radius:20px;font-size:10px;padding:5px 9px}.item-details .primary{min-height:45px;font-size:13px;padding:10px}.item-details .primary>span{font-size:17px}@media(max-height:660px){.detail-model{height:150px;width:180px}.detail-story{font-size:11px;margin:10px 0}.detail-routes{margin:10px 0 13px;padding:9px}.item-details h2{font-size:22px}}
@media(max-width:350px){.top{gap:5px}.logo{gap:5px}.logo>i{width:32px;height:32px;font-size:22px;flex-shrink:0}.logo>span{font-size:9px;letter-spacing:.8px;white-space:nowrap}.logo small{font-size:6px;letter-spacing:.3px;white-space:nowrap}.top .icon{height:33px;width:33px;font-size:18px}.top .wallet{padding:5px 9px;font-size:12px;gap:3px}.size-readout>span{max-width:135px}.collect-readout{right:14px;width:116px}.race{padding:13px}.place{padding:7px 9px}.race-chapter>small{font-size:8px}.race-chapter>b{font-size:13px}}

.collect-readout>span.combo{font-size:14px;color:#c48f42;font-weight:1000}.album-grid{scrollbar-width:thin;scrollbar-color:#a9b79b #eee8d1;scroll-behavior:smooth}.album-grid::-webkit-scrollbar{width:5px}.album-grid::-webkit-scrollbar-thumb{border-radius:5px;background:#a9b79b}.standings-note{font-size:11px;line-height:1.9;color:#85947e}.final-ranking>div{padding:11px 10px}.final-ranking b{font-size:11px}.result [data-action="standings"]{font-size:10px;padding-top:12px}.result [data-action="home"]{font-size:10px;padding-top:10px}

@media(min-aspect-ratio:6/5){.race-chapter>b{font-size:20px}.race-chapter>small{font-size:11px}.race-chapter>span{font-size:13px}.place>b{font-size:36px}.place small{font-size:10px}.size-readout>b{font-size:52px}.size-readout>small{font-size:11px}.size-readout>span{font-size:10px;max-width:220px}.collect-readout{width:175px;padding:10px 12px}.collect-readout>b{font-size:12px}.collect-readout>small{font-size:10px}.tip{font-size:12px}.lane-indicator>span{font-size:10px}.power-button,.jump-button{width:100px;height:108px}.power-button>b,.jump-button>b{font-size:14px}.power-button>small{font-size:11px}.steer-buttons{left:145px}.lane-indicator{left:182px;bottom:95px}.steer-buttons button{width:43px;height:43px}.home .home-bottom{width:360px}.home .home-bottom .primary{font-size:19px;min-height:60px}.home .route-line{font-size:11px}.home .route-line>b{font-size:14px}.home .route-line>button{font-size:11px}.home .secondary{font-size:13px}}

.chapter-toast{top:195px;left:25px;right:25px;padding:14px 9px;border-radius:20px}.chapter-toast>b{font-size:24px;margin:5px 0}.chapter-toast>small{font-size:8px}.chapter-toast>span{font-size:10px}@media(max-height:660px){.chapter-toast{top:165px;padding:12px 8px}.chapter-toast>b{font-size:21px}}@media(min-aspect-ratio:6/5){.chapter-toast{top:145px;left:50%;right:auto;transform:translateX(-50%);width:410px}.chapter-toast>b{font-size:27px}}

.panel{scrollbar-width:thin;scrollbar-color:#b7c0a3 transparent}.panel::-webkit-scrollbar{width:4px}.panel::-webkit-scrollbar-thumb{background:#b7c0a3;border-radius:6px}.result-footer{display:flex;justify-content:center;align-items:center;gap:18px;margin-top:5px}.result .result-footer .text-button{margin:0;padding:8px 0 2px;font-size:10px;white-space:nowrap}

.hero>.eyebrow{display:block}

#size{transform-origin:left center;transition:transform .16s,color .16s}#size.growing{transform:scale(1.07);color:#3e947c}#growth-status{font-size:10px;letter-spacing:.2px;color:#a47e3e;margin-top:4px;max-width:170px;line-height:1.4}@media(max-height:660px){#growth-status{font-size:8px;max-width:135px}}@media(min-aspect-ratio:6/5){#growth-status{font-size:12px;max-width:220px}}
